<?php require 'includes/config.php';if(user())redirect('account.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)$error='Enter a valid name, email and password of at least 8 characters.';else{try{$s=db()->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),'customer']);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'role'=>'customer'];redirect('account.php');}catch(PDOException $ex){$error='Unable to register. This email may already exist.';}}}$pageTitle='Create Account';require 'includes/header.php';?><section class="container section-space"><div class="auth-panel"><div class="eyebrow">JOIN SAHORA</div><h1 class="page-title">Create <em>Account</em></h1><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label mt-3">Full Name</label><input class="form-control" name="name" required maxlength="120"><label class="form-label mt-3">Email</label><input class="form-control" type="email" name="email" required><label class="form-label mt-3">Password (8+ characters)</label><input class="form-control" type="password" name="password" minlength="8" required><button class="btn btn-gold w-100 mt-4">CREATE ACCOUNT</button></form><p class="mt-3">Already registered? <a href="login.php" class="text-gold">Sign in</a></p></div></section><?php require 'includes/footer.php';?>